  marketPreferences: string[];
  growthPreferences: string[];
  capitalEfficiency: string[];
  hardConstraints: string[];
  softPreferences: string[];
  weights: Partial<Record<string, number>>;
  killCriteria: string[];
  exceptions: string[];
};

export const PIPELINE_SCORE_KEYS: ScoreKey[] = [
  "thesisFit",
  "opportunityQuality",
  "risk",
  "uncertainty",
  "evidenceConfidence",
  "valuationAttractiveness",
  "investmentConviction",
];

import type {
  Claim,
  DealIntelligence,
  OpportunityBreakdown,
  Question,
  ScoreKey,
  ScoreSet,
  ThesisSettings,
  CompanyProfile,
  ThesisAssessment,
} from "./types";

export const CONVICTION_WEIGHTS = {
  opportunityQuality: 0.28,
  thesisFit: 0.12,
  riskInverse: 0.18,
  uncertaintyInverse: 0.12,
  evidenceConfidence: 0.12,
  valuationAttractiveness: 0.12,
  portfolioFit: 0.06,
} as const;

export function clampScore(n: number): number {
  return Math.max(0, Math.min(100, Math.round(n)));
}

export function computeConviction(scores: ScoreSet): number {
  const oq = scores.opportunityQuality ?? 0;
  const fit = scores.thesisFit ?? 0;
  const risk = scores.risk ?? 50;
  const unc = scores.uncertainty ?? 50;
  const ev = scores.evidenceConfidence ?? 0;
  const val = scores.valuationAttractiveness ?? 50;
  const port = scores.portfolioFit ?? 50;
  return clampScore(
    CONVICTION_WEIGHTS.opportunityQuality * oq +
      CONVICTION_WEIGHTS.thesisFit * fit +
      CONVICTION_WEIGHTS.riskInverse * (100 - risk) +
      CONVICTION_WEIGHTS.uncertaintyInverse * (100 - unc) +
      CONVICTION_WEIGHTS.evidenceConfidence * ev +
      CONVICTION_WEIGHTS.valuationAttractiveness * val +
      CONVICTION_WEIGHTS.portfolioFit * port,
  );
}

export function computeOpportunity(parts: OpportunityBreakdown): number {
  const values = Object.values(parts);
  return clampScore(values.reduce((sum, n) => sum + n, 0) / values.length);
}

export function computeEvidenceConfidence(input: {
  claims: Claim[];
  questions: Question[];
  missingDocs: number;
}): number {
  const { claims, questions, missingDocs } = input;
  if (!claims.length) return 12;
  const verified = claims.filter((c) => c.verification === "verified").length;
  const contradicted = claims.filter((c) => c.verification === "contradicted").length;
  const openQ = questions.filter((q) => q.status === "open" || q.status === "asked").length;
  const base = (verified / claims.length) * 70 + 20;
  return clampScore(base - contradicted * 10 - openQ * 4 - missingDocs * 6);
}

export function assessThesis(profile: CompanyProfile, thesis: ThesisSettings): ThesisAssessment {
  const matches: ThesisAssessment["matches"] = [];
  const mismatches: ThesisAssessment["mismatches"] = [];
  const exceptions: ThesisAssessment["exceptions"] = [];
  const warnings: string[] = [];

  const sectorPreferred = thesis.preferredSectors.some((s) =>
    profile.sector.toLowerCase().includes(s.toLowerCase()),
  );
  const sectorAvoided = thesis.avoidedSectors.some((s) =>
    profile.sector.toLowerCase().includes(s.toLowerCase()),
  );
  if (sectorPreferred) {
    matches.push({
      label: "Sector",
      matches: true,
      detail: `${profile.sector} sits inside ${thesis.preferredSectors.join(", ")}.`,
    });
  } else if (sectorAvoided) {
    exceptions.push({
      label: "Sector — thesis exception",
      matches: false,
      detail: `${profile.sector} is on the avoided list. This is a warning, not a rejection.`,
    });
    warnings.push(`Hard-constraint warning: avoided sector (${profile.sector}). Continue evaluating.`);
  } else {
    mismatches.push({
      label: "Sector",
      matches: false,
      detail: `${profile.sector} is outside preferred sectors, not on the kill list.`,
    });
  }

  const stageOk = thesis.preferredStages.some((s) =>
    profile.stage.toLowerCase().includes(s.toLowerCase()),
  );
  (stageOk ? matches : mismatches).push({
    label: "Stage",
    matches: stageOk,
    detail: `${profile.stage} vs preferred ${thesis.preferredStages.join(", ")}.`,
  });

  const geoOk = thesis.preferredGeographies.some((g) =>
    profile.geography.toLowerCase().includes(g.toLowerCase()),
  );
  (geoOk ? matches : mismatches).push({
    label: "Geography",
    matches: geoOk,
    detail: `${profile.geography} vs ${thesis.preferredGeographies.join(", ")}.`,
  });

  const raise = profile.fundraise.toLowerCase();
  const checkOk =
    raise.includes("seed") ||
    raise.includes("series a") ||
    raise.includes("$") ||
    thesis.preferredStages.length > 0;
  if (checkOk) {
    matches.push({
      label: "Check size / raise",
      matches: true,
      detail: `${profile.fundraise}. Fund writes ${thesis.checkSizeMin}–${thesis.checkSizeMax}.`,
    });
  }

  const matched = matches.length;
  const penalized = mismatches.length + exceptions.length * 1.5;
  const score = clampScore(58 + matched * 10 - penalized * 8);

  return {
    score,
    matches,
    mismatches,
    exceptions,
    whyItMayStillMatter: exceptions.length
      ? "A thesis miss can still be an attractive investment. Score the company, then decide whether the exception is worth the allocation."
      : mismatches.length
        ? "The miss is a preference, not a kill. Opportunity quality and price still decide."
        : "The deal sits inside the stated mandate. Thesis fit is a component of conviction, not a gate.",
    hardConstraintWarnings: warnings,
  };
}

export function applyOverrides(scores: ScoreSet, intel: DealIntelligence): ScoreSet {
  const next = { ...scores };
  for (const over of intel.overrides) {
    next[over.key] = over.value;
  }
  return next;
}

export function effectiveScores(intel: DealIntelligence): ScoreSet {
  const computed: ScoreSet = { ...intel.scores };
  if (
    computed.opportunityQuality == null &&
    intel.scoreBreakdown?.opportunity
  ) {
    computed.opportunityQuality = computeOpportunity(intel.scoreBreakdown.opportunity);
  }
  if (computed.investmentConviction == null && hasConvictionInputs(computed)) {
    computed.investmentConviction = computeConviction(computed);
  }
  return applyOverrides(computed, intel);
}

function hasConvictionInputs(scores: ScoreSet): boolean {
  return (
    scores.opportunityQuality != null ||
    scores.thesisFit != null ||
    scores.risk != null
  );
}

export function scoreTone(key: ScoreKey, value?: number): string {
  if (value == null) return "text-paper/40";
  if (key === "risk" || key === "uncertainty") {
    if (value >= 70) return "text-flag-red";
    if (value >= 50) return "text-flag-amber";
    return "text-ledger";
  }
  if (value >= 70) return "text-ledger";
  if (value >= 45) return "text-flag-amber";
  return "text-flag-red";
}

export function convictionCopy(): string {
  return "How strong is the investment case right now — not the probability that we write the check.";
}

import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { repoRoot } from "../diligence/paths";
import type { ThesisSettings } from "./types";

function thesisDir() {
  return path.join(repoRoot(), "data", "thesis");
}

function currentPath() {
  return path.join(thesisDir(), "current.json");
}

function historyPath(version: number) {
  return path.join(thesisDir(), "history", `v${version}.json`);
}

export function defaultThesis(): ThesisSettings {
  return {
    version: 1,
    updatedAt: "2026-08-01T12:00:00.000Z",
    preferredSectors: ["climate", "industrial", "B2B infrastructure", "robotics", "logistics"],
    avoidedSectors: ["consumer social", "clinic-first healthcare", "gaming"],
    preferredStages: ["Seed", "Series A"],
    preferredGeographies: ["United States", "EU"],
    checkSizeMin: "$500k",
    checkSizeMax: "$3M",
    businessModels: ["B2B", "usage or seat", "hardware-enabled software"],
    founderPreferences: ["domain operators", "repeat technical founders"],
    marketPreferences: ["painful workflow", "budget already exists"],
    growthPreferences: ["efficient growth over paid blitz"],
    capitalEfficiency: ["path to 18+ months runway on this round"],
    hardConstraints: [
      "No clinic-first healthcare services",
      "No consumer social",
      "Must be able to take a $500k–$3M check",
    ],
    softPreferences: [
      "Industrial or climate adjacency",
      "US or EU HQ",
      "Seed or Series A",
    ],
    weights: {
      sector: 24,
      stage: 16,
      geography: 12,
      businessModel: 16,
      founders: 16,
      capital: 16,
    },
    killCriteria: [
      "Fraud or fabricated metrics",
      "Cap table that cannot accept our check",
    ],
    exceptions: [
      "Healthcare tooling that is infrastructure, not a clinic, may be an exception.",
      "A category-defining founder can override a sector miss — flag it, do not auto-pass.",
    ],
  };
}

export async function loadThesis(): Promise<ThesisSettings> {
  try {
    const raw = await readFile(currentPath(), "utf8");
    return JSON.parse(raw) as ThesisSettings;
  } catch {
    const thesis = defaultThesis();
    await saveThesis(thesis, { skipHistory: true });
    return thesis;
  }
}

export async function saveThesis(
  thesis: ThesisSettings,
  opts?: { skipHistory?: boolean },
): Promise<ThesisSettings> {
  const dir = thesisDir();
  await mkdir(path.join(dir, "history"), { recursive: true });
  const current = { ...thesis, updatedAt: new Date().toISOString() };
  if (!opts?.skipHistory) {
    try {
      const prev = JSON.parse(await readFile(currentPath(), "utf8")) as ThesisSettings;
      await writeFile(historyPath(prev.version), JSON.stringify(prev, null, 2));
      current.version = prev.version + 1;
    } catch {
      current.version = thesis.version || 1;
    }
  }
  await writeFile(currentPath(), JSON.stringify(current, null, 2));
  return current;
}

import { loadDeal, saveDeal } from "../diligence/store";
import type { Deal } from "../diligence/types";
import { computeConviction, effectiveScores } from "./scores";
import type { DealIntelligence, ScoreKey } from "./types";

export async function loadIntelligence(id: string): Promise<{ deal: Deal; intel: DealIntelligence } | null> {
  const deal = await loadDeal(id);
  if (!deal?.intelligence) return null;
  return { deal, intel: deal.intelligence };
}

export async function saveIntelligence(deal: Deal, intel: DealIntelligence): Promise<Deal> {
  const scores = effectiveScores(intel);
  if (hasAnyScore(scores) && scores.investmentConviction == null) {
    scores.investmentConviction = computeConviction(scores);
  }
  intel.scores = scores;
  deal.intelligence = intel;
  deal.updatedAt = new Date().toISOString();
  await saveDeal(deal);
  return deal;
}

export async function applyScoreOverride(
  id: string,
  key: ScoreKey,
  value: number,
  reason: string,
): Promise<Deal | null> {
  const loaded = await loadIntelligence(id);
  if (!loaded) return null;
  const { deal, intel } = loaded;
  const previous = intel.scores[key] ?? null;
  intel.overrides = intel.overrides.filter((item) => item.key !== key);
  intel.overrides.push({
    key,
    value,
    reason,
    at: new Date().toISOString(),
  });
  intel.scoreChanges.push({
    id: `override-${key}-${Date.now()}`,
    key,
    previous,
    next: value,
    reason,
    date: new Date().toISOString(),
    source: "VC override",
  });
  intel.timeline.push({
    id: `tl-override-${Date.now()}`,
    at: new Date().toISOString(),
    title: `Override: ${key}`,
    body: reason,
    source: "VC",
  });
  return saveIntelligence(deal, intel);
}

export async function applyFounderReply(id: string): Promise<Deal | null> {
  const loaded = await loadIntelligence(id);
  if (!loaded) return null;
  const { deal, intel } = loaded;
  if (intel.founderReplyApplied) return deal;

  const question = intel.questions.find((item) => item.id === "q-arr");
  if (question) {
    question.status = "answered";
  }
  const prev = intel.scores.investmentConviction ?? 52;
  const next = Math.min(100, prev + 5);
  intel.scores.investmentConviction = next;
  intel.scores.evidenceConfidence = Math.min(100, (intel.scores.evidenceConfidence ?? 38) + 8);
  intel.scores.uncertainty = Math.max(0, (intel.scores.uncertainty ?? 62) - 7);
  intel.founderReplyApplied = true;
  intel.nextAction = {
    title: "Ask for the customer-cohort workbook",
    reason: "ARR definition is now stated. The remaining decision value is retention quality.",
    decisionImpact: "high",
    informationValue: "high",
    cost: "low",
    time: "3 days",
    urgency: "this_week",
  };
  intel.scoreChanges.push({
    id: "sc-founder-arr",
    key: "investmentConviction",
    previous: prev,
    next,
    reason: "Founder restated ARR as billed + contracted, and sent the monthly roll-forward.",
    evidence: "Founder email 12 Sep · model v3",
    date: new Date().toISOString(),
    source: "Founder reply",
  });
  intel.timeline.push({
    id: "tl-founder-arr",
    at: new Date().toISOString(),
    title: "Founder answered the ARR question",
    body: "Definition aligned. Conviction +5. Next: cohort workbook.",
    source: "Founder loop",
  });
  return saveIntelligence(deal, intel);
}

function hasAnyScore(scores: DealIntelligence["scores"]): boolean {
  return Object.values(scores).some((value) => value != null);
}

