"use client";

import Link from "next/link";
import { useMemo, useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { DealSummary } from "@/lib/diligence/types";
import { DEAL_STAGES, STAGE_LABELS, type DealStage } from "@/lib/intelligence/types";
import { scoreTone } from "@/lib/intelligence/scores";
import { scoreDisplay, when } from "@/lib/format";

type SortKey =
  | "company"
  | "stage"
  | "thesisFit"
  | "opportunityQuality"
  | "riskScore"
  | "uncertainty"
  | "evidenceConfidence"
  | "valuationAttractiveness"
  | "investmentConviction"
  | "lastActivity";

type Props = {
  deals: DealSummary[];
};

const COLUMNS: { key: SortKey; label: string }[] = [
  { key: "company", label: "Company" },
  { key: "stage", label: "Stage" },
  { key: "thesisFit", label: "Thesis" },
  { key: "opportunityQuality", label: "Opportunity" },
  { key: "riskScore", label: "Risk" },
  { key: "uncertainty", label: "Uncertainty" },
  { key: "evidenceConfidence", label: "Evidence" },
  { key: "valuationAttractiveness", label: "Valuation" },
  { key: "investmentConviction", label: "Conviction" },
];

export function PipelineBoard({ deals }: Props) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [stage, setStage] = useState<DealStage | "all">("all");
  const [sort, setSort] = useState<SortKey>("stage");
  const [dir, setDir] = useState<"asc" | "desc">("asc");
  const [error, setError] = useState<string | null>(null);

  const rows = useMemo(() => {
    const filtered = deals.filter((deal) => (stage === "all" ? true : deal.stage === stage));
    const sign = dir === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      if (sort === "company") return sign * (a.company || a.name).localeCompare(b.company || b.name);
      if (sort === "stage") {
        const ai = DEAL_STAGES.indexOf(a.stage as DealStage);
        const bi = DEAL_STAGES.indexOf(b.stage as DealStage);
        return sign * ((ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi));
      }
      if (sort === "lastActivity") {
        return sign * (a.lastActivity ?? "").localeCompare(b.lastActivity ?? "");
      }
      const av = (a[sort] as number | undefined) ?? -1;
      const bv = (b[sort] as number | undefined) ?? -1;
      return sign * (av - bv);
    });
  }, [deals, stage, sort, dir]);

  function toggleSort(key: SortKey) {
    if (sort === key) setDir((d) => (d === "asc" ? "desc" : "asc"));
    else {
      setSort(key);
      setDir(key === "company" || key === "stage" ? "asc" : "desc");
    }
  }

  function reseeds() {
    setError(null);
    startTransition(async () => {
      const res = await fetch("/api/deals/seed", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ force: true }),
      });
      if (!res.ok) {
        setError("Could not reload the five sample deals.");
        return;
      }
      router.refresh();
    });
  }

  return (
    <section aria-labelledby="pipeline-heading">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h2 id="pipeline-heading" className="font-serif text-3xl">
            Pipeline
          </h2>
          <p className="mt-2 max-w-xl text-[15px] leading-6 text-paper/65">
            Thesis mismatch is a flag, never a gate. Five live deals. Sort and filter, then open a
            company.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <label className="font-mono text-[11px] uppercase tracking-[0.08em] text-paper/45">
            Stage
            <select
              value={stage}
              onChange={(event) => setStage(event.target.value as DealStage | "all")}
              className="ml-2 border border-white/15 bg-desk px-2 py-1 text-[12px] text-paper"
            >
              <option value="all">All</option>
              {DEAL_STAGES.map((item) => (
                <option key={item} value={item}>
                  {STAGE_LABELS[item]}
                </option>
              ))}
            </select>
          </label>
          <button
            type="button"
            onClick={reseeds}
            disabled={pending}
            className="border border-white/15 px-3 py-1.5 text-[13px] text-paper/70 hover:text-paper disabled:opacity-50"
          >
            {pending ? "Reloading…" : "Reload sample book"}
          </button>
        </div>
      </div>

      <div className="mt-6 overflow-x-auto">
        <table className="pipe-table">
          <thead>
            <tr>
              {COLUMNS.map((col) => (
                <th key={col.key}>
                  <button type="button" onClick={() => toggleSort(col.key)}>
                    {col.label}
                    {sort === col.key ? (dir === "asc" ? " ↑" : " ↓") : ""}
                  </button>
                </th>
              ))}
              <th>Next action</th>
              <th>
                <button type="button" onClick={() => toggleSort("lastActivity")}>
                  Last activity
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((deal) => (
              <tr key={deal.id} className={deal.thesisException ? "is-exception" : undefined}>
                <td>
                  <Link href={`/deals/${deal.id}`} className="font-serif text-[18px] text-paper hover:text-white">
                    {deal.company || deal.name}
                  </Link>
                  {deal.thesisException ? (
                    <p className="mt-1 font-mono text-[10px] uppercase tracking-[0.08em] text-flag-amber">
                      Thesis exception
                    </p>
                  ) : null}
                </td>
                <td className="font-mono text-[11px] text-copper">
                  {deal.stage ? STAGE_LABELS[deal.stage] : "—"}
                </td>
                <td className={scoreTone("thesisFit", deal.thesisFit)}>{scoreDisplay(deal.thesisFit)}</td>
                <td className={scoreTone("opportunityQuality", deal.opportunityQuality)}>
                  {scoreDisplay(deal.opportunityQuality)}
                </td>
                <td className={scoreTone("risk", deal.riskScore)}>{scoreDisplay(deal.riskScore)}</td>
                <td className={scoreTone("uncertainty", deal.uncertainty)}>{scoreDisplay(deal.uncertainty)}</td>
                <td className={scoreTone("evidenceConfidence", deal.evidenceConfidence)}>
                  {scoreDisplay(deal.evidenceConfidence)}
                </td>
                <td className={scoreTone("valuationAttractiveness", deal.valuationAttractiveness)}>
                  {scoreDisplay(deal.valuationAttractiveness)}
                </td>
                <td className={scoreTone("investmentConviction", deal.investmentConviction)}>
                  {scoreDisplay(deal.investmentConviction)}
                </td>
                <td className="max-w-[16rem] text-[13px] text-paper/70">{deal.nextAction ?? "—"}</td>
                <td className="whitespace-nowrap text-[12px] text-paper/50">{when(deal.lastActivity)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {error ? <p className="mt-3 text-[14px] text-flag-red">{error}</p> : null}
    </section>
  );
}

