type Props = { thesis: ThesisSettings };

function lines(value: string) {
  return value
    .split("\n")
    .map((item) => item.trim())
    .filter(Boolean);
}

function Field({
  label,
  hint,
  value,
  onChange,
  multiline,
}: {
  label: string;
  hint?: string;
  value: string;
  onChange: (value: string) => void;
  multiline?: boolean;
}) {
  return (
    <label className="block">
      <span className="font-mono text-[11px] uppercase tracking-[0.08em] text-copper">{label}</span>
      {hint ? <span className="mt-1 block text-[13px] text-paper/50">{hint}</span> : null}
      {multiline ? (
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          rows={4}
          className="mt-2 w-full border border-white/15 bg-transparent px-3 py-2 text-[15px] leading-6"
        />
      ) : (
        <input
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="mt-2 w-full border-b border-white/20 bg-transparent py-2 text-[15px]"
        />
      )}
    </label>
  );
}

export function ThesisForm({ thesis }: Props) {
  const router = useRouter();
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [preferredSectors, setPreferredSectors] = useState(thesis.preferredSectors.join("\n"));
  const [avoidedSectors, setAvoidedSectors] = useState(thesis.avoidedSectors.join("\n"));
  const [preferredStages, setPreferredStages] = useState(thesis.preferredStages.join("\n"));
  const [preferredGeographies, setPreferredGeographies] = useState(thesis.preferredGeographies.join("\n"));
  const [checkSizeMin, setCheckSizeMin] = useState(thesis.checkSizeMin);
  const [checkSizeMax, setCheckSizeMax] = useState(thesis.checkSizeMax);
  const [businessModels, setBusinessModels] = useState(thesis.businessModels.join("\n"));
  const [founderPreferences, setFounderPreferences] = useState(thesis.founderPreferences.join("\n"));
  const [marketPreferences, setMarketPreferences] = useState(thesis.marketPreferences.join("\n"));
  const [growthPreferences, setGrowthPreferences] = useState(thesis.growthPreferences.join("\n"));
  const [capitalEfficiency, setCapitalEfficiency] = useState(thesis.capitalEfficiency.join("\n"));
  const [hardConstraints, setHardConstraints] = useState(thesis.hardConstraints.join("\n"));
  const [softPreferences, setSoftPreferences] = useState(thesis.softPreferences.join("\n"));
  const [killCriteria, setKillCriteria] = useState(thesis.killCriteria.join("\n"));
  const [exceptions, setExceptions] = useState(thesis.exceptions.join("\n"));

  return (
    <form
      className="grid gap-6"
      onSubmit={(event) => {
        event.preventDefault();
        setError(null);
        const next: ThesisSettings = {
          ...thesis,
          preferredSectors: lines(preferredSectors),
          avoidedSectors: lines(avoidedSectors),
          preferredStages: lines(preferredStages),
          preferredGeographies: lines(preferredGeographies),
          checkSizeMin,
          checkSizeMax,
          businessModels: lines(businessModels),
          founderPreferences: lines(founderPreferences),
          marketPreferences: lines(marketPreferences),
          growthPreferences: lines(growthPreferences),
          capitalEfficiency: lines(capitalEfficiency),
          hardConstraints: lines(hardConstraints),
          softPreferences: lines(softPreferences),
          killCriteria: lines(killCriteria),
          exceptions: lines(exceptions),
        };
        start(async () => {
          const res = await fetch("/api/thesis", {
            method: "PUT",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(next),
          });
          if (!res.ok) {
            setError("Could not save the thesis.");
            return;
          }
          router.refresh();
        });
      }}
    >
      <p className="text-[14px] text-paper/60">
        Version {thesis.version}. Each save writes a history snapshot. Hard constraints produce
        warnings and thesis exceptions — never an automatic pass.
      </p>
      <div className="grid gap-6 md:grid-cols-2">
        <Field label="Preferred sectors" multiline value={preferredSectors} onChange={setPreferredSectors} />
        <Field
          label="Avoided sectors"
          hint="Warning / exception, not a kill switch."
          multiline
          value={avoidedSectors}
          onChange={setAvoidedSectors}
        />
        <Field label="Preferred stages" multiline value={preferredStages} onChange={setPreferredStages} />
        <Field label="Preferred geographies" multiline value={preferredGeographies} onChange={setPreferredGeographies} />
        <Field label="Check size min" value={checkSizeMin} onChange={setCheckSizeMin} />
        <Field label="Check size max" value={checkSizeMax} onChange={setCheckSizeMax} />
        <Field label="Business models" multiline value={businessModels} onChange={setBusinessModels} />
        <Field label="Founder preferences" multiline value={founderPreferences} onChange={setFounderPreferences} />
        <Field label="Market preferences" multiline value={marketPreferences} onChange={setMarketPreferences} />
        <Field label="Growth preferences" multiline value={growthPreferences} onChange={setGrowthPreferences} />
        <Field label="Capital efficiency" multiline value={capitalEfficiency} onChange={setCapitalEfficiency} />
        <Field label="Hard constraints" multiline value={hardConstraints} onChange={setHardConstraints} />
        <Field label="Soft preferences" multiline value={softPreferences} onChange={setSoftPreferences} />
        <Field label="Kill criteria" hint="True kills — fraud, broken cap table — not thesis taste." multiline value={killCriteria} onChange={setKillCriteria} />
        <Field label="Named exceptions" multiline value={exceptions} onChange={setExceptions} />
      </div>
      <button
        type="submit"
        disabled={pending}
        className="w-fit bg-paper px-5 py-3 text-[15px] text-ink disabled:opacity-50"
      >
        {pending ? "Saving…" : "Save thesis"}
      </button>
      {error ? <p className="text-flag-red">{error}</p> : null}
    </form>
  );
}

