curl -sS -o /tmp/nd-home.html -w "home:%{http_code}\n" http://127.0.0.1:3000/ && curl -sS -o /tmp/nd-lumen.html -w "lumen:%{http_code}\n" http://127.0.0.1:3000/deals/lumen-health && curl -sS -o /tmp/nd-helio.html -w "helio:%{http_code}\n" "http://127.0.0.1:3000/deals/helio-freight?tab=decision" && curl -sS -o /tmp/nd-thesis.html -w "thesis:%{http_code}\n" http://127.0.0.1:3000/thesis && python3 - <<'PY'
from pathlib import Path
checks = {
  "/tmp/nd-home.html": ["Pipeline", "HarborMail", "Thesis exception", "Light"],
  "/tmp/nd-lumen.html": ["Overview", "Thesis", "Numbers", "Decision", "Take meeting"],
  "/tmp/nd-helio.html": ["Advance with conditions", "What changed my mind"],
  "/tmp/nd-thesis.html": ["We like", "We avoid", "Hard constraints"],
}
for path, needles in checks.items():
    text = Path(path).read_text(errors="ignore")
    missing = [n for n in needles if n not in text]
    extras = []
    if path == "/tmp/nd-lumen.html":
        for n in ["Evidence", "Findings", "World", "Valuation", "People + Product"]:
            if n in text and f">{n}<" in text.replace(" ", ""):
                extras.append(n)
    print(path, "OK" if not missing else "MISSING "+str(missing), extras)
PY

