      return;
    }
    if (cmd === "status") {
      console.log(JSON.stringify(await statusDemo(a || LIVE_DEAL_ID), null, 2));
      return;
    }
    if (cmd === "decide") {
      const id = a || LIVE_DEAL_ID;
      if (!b || !c) {
